fn contains_z(s: &str) -> bool {
    // Requires: s is a valid string slice
    // Ensures: returns true if 'z' or 'Z' is present in the string, false otherwise
    // Decreases: the length of the string being processed
    // Invariant: at any point, the characters processed so far do not include 'z' or 'Z'
    let mut found_z = false;
    for c in s.chars() {
        // Assert: c is a character from the string
        assert!(c.is_ascii()); // Assuming we are only dealing with ASCII characters
        if c == 'z' || c == 'Z' {
            found_z = true;
            break;
        }
    }
    found_z
}

